const express = require('express');
const QuickLRU = require('quick-lru');

const app = express();
const analyticsCache = new QuickLRU({ maxSize: 1000 });

app.get('/api/metrics/cached-summary', (req, res) => {
  const { metricType } = req.query;
  if (!metricType) {
    return res.status(400).json({ error: 'Missing metricType parameter' });
  }

  // Construct cache key strictly scoped to the authenticated user's organization
  const safeCacheKey = `org_${req.user.organizationId}_${metricType}`;
  const cachedSummary = analyticsCache.get(safeCacheKey);
  if (!cachedSummary) {
    return res.status(404).json({ error: 'Summary not in cache' });
  }

  return res.json({
    key: safeCacheKey,
    metrics: cachedSummary
  });
});

module.exports = app;
